/* eslint-disable max-len */

'use strict';

// MODULES //

var chRef = require( './ch_ref.js' );
var ccRef = require( './cc_ref.js' );


// MAIN //

/**
* Performs the forward FFT of length 2 for real-valued sequences.
*
* @private
* @param {number} ido - number of real values for each transform
* @param {number} l1 - length of the input sequences
* @param {Float64Array} cc - input array containing sequences to be transformed
* @param {number} ccOffset - offset for the input array
* @param {Float64Array} ch - output array containing transformed sequences
* @param {number} chOffset - offset for the output array
* @param {Float64Array} wa1 - array of twiddle factors
* @param {number} wa1Offset - offset for the twiddle factors array
* @returns {void}
*/
function radf2( ido, l1, cc, ccOffset, ch, chOffset, wa1, wa1Offset ) {
	var idp2;
	var tr2;
	var ti2;
	var ic;
	var i;
	var k;

	// Parameter adjustments...
	chOffset -= 1 + ( ido * 3 );
	ccOffset -= 1 + ( ido * ( 1 + l1 ) );
	wa1Offset -= 1;

	// Function body:
	for ( k = 1; k <= l1; k++ ) {
		ch[ chRef( 1, 1, k, l1, ido ) + chOffset ] = cc[ ccRef( 1, k, 1, l1, ido ) + ccOffset ] + cc[ ccRef( 1, k, 2, l1, ido ) + ccOffset ];
		ch[ chRef( ido, 2, k, l1, ido ) + chOffset ] = cc[ ccRef( 1, k, 1, l1, ido ) + ccOffset ] - cc[ ccRef( 1, k, 2, l1, ido ) + ccOffset ];
	}
	if ( ido < 2 ) {
		return;
	}
	if ( ido !== 2 ) {
		idp2 = ido + 2;
		for ( k = 1; k <= l1; k++ ) {
			for ( i = 3; i <= ido; i += 2 ) {
				ic = idp2 - i;
				tr2 = ( wa1[ i - 2 + wa1Offset ] * cc[ ccRef( i - 1, k, 2, l1, ido ) + ccOffset ] ) + ( wa1[ i - 1 + wa1Offset ] * cc[ ccRef( i, k, 2, l1, ido ) + ccOffset ] );
				ti2 = ( wa1[ i - 2 + wa1Offset ] * cc[ ccRef( i, k, 2, l1, ido ) + ccOffset ] ) - ( wa1[ i - 1 + wa1Offset ] * cc[ ccRef( i - 1, k, 2, l1, ido ) + ccOffset ] );
				ch[ chRef( i, 1, k, l1, ido ) + chOffset ] = cc[ ccRef( i, k, 1, l1, ido ) + ccOffset ] + ti2;
				ch[ chRef( ic, 2, k, l1, ido ) + chOffset ] = ti2 - cc[ ccRef( i, k, 1, l1, ido ) + ccOffset ];
				ch[ chRef( i - 1, 1, k, l1, ido ) + chOffset ] = cc[ ccRef( i - 1, k, 1, l1, ido ) + ccOffset ] + tr2;
				ch[ chRef( ic - 1, 2, k, l1, ido ) + chOffset ] = cc[ ccRef( i - 1, k, 1, l1, ido ) + ccOffset ] - tr2;
			}
		}
		if ( ido % 2 === 1 ) {
			return;
		}
	}
	for ( k = 1; k <= l1; k++ ) {
		ch[ chRef( 1, 2, k, l1, ido ) + chOffset ] = -cc[ ccRef( ido, k, 2, l1, ido ) + ccOffset ];
		ch[ chRef( ido, 1, k, l1, ido ) + chOffset ] = -cc[ ccRef( ido, k, 1, l1, ido ) + ccOffset ];
	}
}


// EXPORTS //

module.exports = radf2;
